def main():
	allans = []
	t = int(input())
	for _ in range(t):
		input()
		(n, k) = readIntArr()
		adj = [[] for __ in range(n)]
		for __ in range(n - 1):
			(u, v) = readIntArr()
			u -= 1
			v -= 1
			adj[u].append(v)
			adj[v].append(u)
		if k == 2:
			allans.append(n * (n - 1) // 2)
			continue
		centralNodes = []
		for node in range(n):
			if len(adj[node]) >= k:
				centralNodes.append(node)
		ans = 0
		for cn in centralNodes:
			v = [False] * n
			v[cn] = True
			groups = []
			for nex in adj[cn]:
				v[nex] = True
				groups.append([nex])
			while len(groups) >= k:
				N = len(groups)
				M = k
				dp = [[0 for __ in range(M + 1)] for ___ in range(N)]
				for i in range(N):
					dp[i][0] = 1
				dp[0][1] = len(groups[0])
				for i in range(1, N):
					for j in range(1, M + 1):
						dp[i][j] = dp[i - 1][j] + dp[i - 1][j - 1] * len(groups[i])
						dp[i][j] %= MOD
				ans += dp[N - 1][M]
				ans %= MOD
				groups2 = []
				for gp in groups:
					temp = []
					for node in gp:
						for nex in adj[node]:
							if v[nex]:
								continue
							v[nex] = True
							temp.append(nex)
					if len(temp) > 0:
						groups2.append(temp)
				groups = groups2
		allans.append(ans)
	multiLineArrayPrint(allans)
	return
